properties.expression:
w = thisComp.layer("CONTROLLER").effect("WIDTH")("Slider"); 
h = thisComp.layer("CONTROLLER").effect("HEIGHT")("Slider");
f = framesToTime(1);
dur = outPoint - inPoint;
mid = inPoint + (dur * 0.5);

if(time < mid){
	ease(time, inPoint , mid - f, [w-w,h], [w,h])
}else{
	ease(time, mid , outPoint - f, [w,h], [w-w,h])	
}

s = content("Rectangle 1").content("Rectangle Path 1").size;
dur = outPoint - inPoint;
mid = inPoint + (dur * 0.5);

value + ((time < mid) ? - [s[0] * 0.5, 0] : [s[0] * 0.5, 0]);

s = thisComp.layer("CONTROLLER").effect("WIDTH")("Slider");
dur = outPoint - inPoint;
mid = inPoint + (dur * 0.5);

value + ((time < mid) ? [0,0] : [s, 0]);
